/// <reference lib="webworker" />
import { Sha256 } from './sha256';

/**
 * Hashing worker.
 *
 * A 10 GB file takes minutes of pure CPU to digest in software. Doing that on
 * the main thread would freeze the UI (and the transfer progress animations)
 * for the whole duration, so the loop lives here. `File`/`Blob` handles are
 * structured-cloneable and read lazily off disk, so posting the File across is
 * cheap — no bytes are copied until `slice().arrayBuffer()`.
 */

export interface HashRequest {
  id: string;
  file: Blob;
  /** Bytes read per slice. Small enough to stay off the large-object heap. */
  sliceSize: number;
}

export type HashResponse =
  | { id: string; type: 'progress'; bytesHashed: number }
  | { id: string; type: 'done'; sha256: string }
  | { id: string; type: 'error'; message: string };

const ctx = self as unknown as DedicatedWorkerGlobalScope;

ctx.addEventListener('message', (event: MessageEvent<HashRequest>) => {
  const { id, file, sliceSize } = event.data;
  void run(id, file, sliceSize);
});

async function run(id: string, file: Blob, sliceSize: number): Promise<void> {
  try {
    const hasher = new Sha256();
    let offset = 0;
    let lastReport = 0;
    while (offset < file.size) {
      const end = Math.min(offset + sliceSize, file.size);
      const buffer = await file.slice(offset, end).arrayBuffer();
      hasher.update(new Uint8Array(buffer));
      offset = end;
      // Throttle progress posts: one per ~48 MB is plenty for a progress bar.
      if (offset - lastReport >= sliceSize * 12 || offset === file.size) {
        lastReport = offset;
        const msg: HashResponse = { id, type: 'progress', bytesHashed: offset };
        ctx.postMessage(msg);
      }
    }
    const done: HashResponse = { id, type: 'done', sha256: hasher.digestHex() };
    ctx.postMessage(done);
  } catch (err) {
    const msg: HashResponse = {
      id,
      type: 'error',
      message: err instanceof Error ? err.message : String(err),
    };
    ctx.postMessage(msg);
  }
}
